fpsrun.script:
var fpsrun_lines = 0;
var fpsrun_timer = maketimer(10, func {
    var frame = getprop("/sim/frame-number") or 0;
    if (!getprop("/sim/sceneryloaded") or (getprop("/sim/startup/splash-alpha") or 0) > 0) {
        print(sprintf("fpsrun waiting: frame %d at %.2f s, splash screen", frame, systime()));
        return;
    }
    fpsrun_lines += 1;
    print(sprintf("fpsrun %d: frame %d at %.2f s, %s", fpsrun_lines, frame,
                  systime(), getprop("/sim/current-view/name") or "-"));
    if (fpsrun_lines == 7)
        setprop("/sim/current-view/view-number", 1);
    if (fpsrun_lines == 13)
        fgcommand("exit");
});
fpsrun_timer.simulatedTime = 0;
fpsrun_timer.start();
